import { publicAssetUrl } from "../iot/resources";
import { useEffect, useRef, useState } from "react";
import { findBuiltinModel } from "../../../../shared/builtin-models";
import type { ModelAsset } from "./model-assets";
import { invalidateModelAssetCover, subscribeModelAssetCover, type ModelAssetCoverState } from "./model-asset-covers";
import "./model-asset-thumbnail.css";

/** Cards display static images; uploaded covers are generated by one shared queue. */
export function ModelAssetThumbnail({ asset, name, onPreview, projectId = asset.projectId, variant = "compact" }: {
  asset: ModelAsset;
  name: string;
  onPreview: () => void;
  projectId?: string;
  variant?: "compact" | "card";
}) {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [visible, setVisible] = useState(false);
  const [attempt, setAttempt] = useState(0);
  const [result, setResult] = useState<{ key: string; state: ModelAssetCoverState } | null>(null);
  const [failedImage, setFailedImage] = useState<string | null>(null);
  const thumbnail = findBuiltinModel(asset.id)?.thumbnailPath;
  const key = JSON.stringify([projectId, asset.id, asset.sha256, asset.source, thumbnail, attempt]);
  const state = result?.key === key ? result.state : null;
  const source = thumbnail ? publicAssetUrl(thumbnail) : state?.status === "ready" ? state.url : undefined;
  const failed = failedImage === key || state?.status === "error";

  useEffect(() => {
    const button = buttonRef.current;
    if (!button) return;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) {
        setVisible(true);
        observer.disconnect();
      }
    }, { rootMargin: "96px" });
    observer.observe(button);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!visible || thumbnail) return;
    return subscribeModelAssetCover({ asset, projectId }, (next) => setResult({ key, state: next }));
  }, [visible, thumbnail, projectId, asset.id, asset.sha256, asset.source, key]);

  const retry = () => {
    if (!thumbnail) invalidateModelAssetCover({ asset, projectId });
    setFailedImage(null);
    setAttempt((previous) => previous + 1);
  };
  return (
    <button aria-label={failed ? `重试 ${name} 的封面` : `预览 ${name}`} className={variant === "card" ? "resource-card-preview model-asset-cover" : "model-asset-thumbnail"}
      data-model-cover-state={failed ? "error" : source && visible ? "ready" : "loading"}
      onClick={failed ? retry : onPreview} ref={buttonRef}
      title={failed ? `${state?.status === "error" ? state.message : "封面图片加载失败"}，点击重试` : `查看 ${name} 的 3D 预览`} type="button">
      {source && visible && !failed ? (
        <img key={key} src={source} alt={`${name} 封面`} decoding="async" draggable={false} loading="lazy" onError={() => {
          console.error("Model cover image failed to load.", { projectId, modelAssetId: asset.id, sha256: asset.sha256 });
          setFailedImage(key);
        }} />
      ) : <span className="model-asset-cover-status">
        {failed ? <>封面生成失败<small>点击重试</small></> : visible ? <>正在生成封面…</> : "封面待加载"}
      </span>}
      {variant === "card" && !failed ? <span className="resource-preview-hint">点击预览</span> : null}
    </button>
  );
}
